/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CompanyChainId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, CompanyChainId))]
internal class GUPPricingAttributeCustTableCompanyChainId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CompanyChainId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    smmBusRelChainGroup smmBusRelChainGroup;

    while select CompanyChainId from custtable
        group by CompanyChainId
        join smmBusRelChainGroup
        group by ChainId, Description
        where custTable.CompanyChainId == smmBusRelChainGroup.ChainId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(smmBusRelChainGroup.ChainId, smmBusRelChainGroup.Description);
        ret.add(valueObject);
    }
    return ret;
}
